queries.automatic_flag_events:
begin read only;
set local statement_timeout='5s';
with flags as materialized (
 select f.id,f.entity_key,f.reason_code,f.state,f.flagged_at,f.updated_at,f.cleared_at,f.released_at,f.next_check_at,f.checks
 from pipeline.enrichment_flags f where f.entity='job' and f.reason_code='idle_paused'
), events as materialized (
 select f.entity_key,e.id,e.flag_id,e.at,e.action,
 case when e.actor_kind='auto' then e.actor else '[person omitted]' end actor,e.actor_kind,
 case when e.actor_kind='auto' then left(e.reason,300) else '[person reason omitted]' end reason,
 jsonb_build_object('mode',e.evidence->'mode','runs',e.evidence->'runs','with_work',e.evidence->'with_work','from',e.evidence->'from','to',e.evidence->'to','check',e.evidence->'check') evidence
 from flags f join lateral (
 select * from pipeline.enrichment_flag_events e where e.flag_id=f.id and e.at>='2026-11-06T13:40:00Z' order by e.at desc,e.id desc limit 100
 ) e on true
)
select now() observed_at,
(select jsonb_agg(jsonb_build_object('jobid',jobid,'name',jobname,'active',active,'schedule',schedule) order by jobid) from cron.job) jobs,
(select jsonb_agg(to_jsonb(f) order by entity_key) from flags f) flags,
(select jsonb_agg(to_jsonb(e) order by at,id) from events e) events,
(select jsonb_agg(jsonb_build_object('jobname',jobname,'paused_at',paused_at,'resumed_at',resumed_at,'last_checked_at',last_checked_at,'last_output',last_output,'last_input',last_input)) from pipeline.job_idle_watch) idle_watch,
(select jsonb_object_agg(key,value) from pipeline.platform_toolset_settings where toolset_key='pipeline' and key in ('jobs.held_off','flag.empty_calls_to_pause','flag.job_recheck_hours','flag.never_pause_modes','flag.answer_wait_seconds')) controls;
commit;
